import 'package:flutter/material.dart';
import 'local_food_catalog.dart';
import 'nutrition_catalog.dart';
class ManualFoodScreen extends StatefulWidget { const ManualFoodScreen({super.key,required this.catalog, this.barcode}); final LocalFoodCatalog catalog; final String? barcode; @override State<ManualFoodScreen> createState()=>_ManualFoodScreenState(); }
class _ManualFoodScreenState extends State<ManualFoodScreen>{final name=TextEditingController(),barcode=TextEditingController(),kcal=TextEditingController(),protein=TextEditingController(),carbs=TextEditingController(),fat=TextEditingController(); @override void initState(){super.initState();barcode.text=widget.barcode??'';} @override void dispose(){for(final c in [name,barcode,kcal,protein,carbs,fat])c.dispose();super.dispose();} double? n(TextEditingController c)=>double.tryParse(c.text.replaceAll(',','.')); Future<void> save()async{final k=n(kcal),p=n(protein),c=n(carbs),f=n(fat);if(name.text.trim().isEmpty||k==null||p==null||c==null||f==null||k<0||p<0||c<0||f<0)return;await widget.catalog.save(barcode:barcode.text.trim().isEmpty?null:barcode.text.trim(),food:FoodItem(name:name.text.trim(),kcalPer100g:k,proteinPer100g:p,carbohydratePer100g:c,fatPer100g:f));if(mounted)Navigator.pop(context,true);} @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Eigenes Lebensmittel')),body:ListView(padding:const EdgeInsets.all(16),children:[_f('Name',name),_f('Barcode (optional)',barcode),_f('Kalorien / 100 g',kcal),_f('Protein / 100 g',protein),_f('Kohlenhydrate / 100 g',carbs),_f('Fett / 100 g',fat),const SizedBox(height:12),FilledButton(onPressed:save,child:const Text('Speichern'))]));Widget _f(String l,TextEditingController c)=>Padding(padding:const EdgeInsets.only(bottom:12),child:TextField(controller:c,keyboardType:l=='Name'?TextInputType.text:const TextInputType.numberWithOptions(decimal:true),decoration:InputDecoration(labelText:l)));}
